import {wholeCases,wholeCopy as copy} from './whole-bundles-content.mjs';
import {createWhole,wholeModel,changeWhole,wholeNames,wholeExample} from './whole-bundles-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const p=(t,speech)=>`<p data-wb-read${speech?` data-wb-speech="${esc(speech)}"`:''}>${esc(t)}</p>`;
const count=(n,word)=>`${n} ${word}${n===1?'':'s'}`;
const button=(a,t,disabled=false)=>`<button type="button" data-wb-action="${a}"${disabled?' disabled':''}>${esc(t)}</button>`;
const numeral=t=>t?`<p class="wb-written">Written <span>${esc(t)}</span></p>`:'';
let visit=null,retire=()=>{},stopBinding=()=>{};
export function resetWholeBundles(){retire();stopBinding();visit=null;retire=()=>{};stopBinding=()=>{};}
function current(book,owner){if(!visit||visit.book!==book||visit.owner!==owner){retire();stopBinding();visit={book,owner,caseId:wholeCases[0].id,cases:new Map(wholeCases.map(c=>[c.id,createWhole(c.id)])),screen:'work',frame:0,caller:'work',grownUp:false};}return visit;}
function readout(m){if(m.numerator===0)return 'There are no ribbon pieces here. Zero stays zero.';return `${count(m.packed,'whole bundle')}, ${count(m.loose,'loose piece')}. ${m.loose?`Each loose piece is 1/${m.denominator} of a whole.`:'No loose pieces.'}`;}
function bundleReason(m){if(m.numerator===0)return 'There are no ribbon pieces here. Zero stays zero.';if(!m.loose)return 'All this ribbon is in whole bundles. Open one to see its pieces.';if(m.loose<m.denominator)return `A whole needs ${m.denominator} pieces. ${m.loose===1?'There is 1 loose piece; keep it as part of a whole.':`There are ${m.loose} loose pieces; keep these as parts of a whole.`}`;return `There are enough loose pieces to bundle ${m.packed?'another':'a'} whole.`;}
function diagram(m,claim=false){const n=m.numerator,d=m.denominator,rows=Math.max(1,Math.ceil(n/d)),step=104;
 const strips=Array.from({length:rows},(_,j)=>{const y=30+j*step,bundled=j<m.packed,filled=Math.min(d,Math.max(0,n-j*d));
  const pieces=Array.from({length:filled},(_,k)=>`<rect data-wb-piece="${j*d+k}" data-role="${bundled?'bundled':'loose'}" x="${48+504*k/d}" y="${y}" width="${504/d}" height="34"/>`).join('');
  const cuts=Array.from({length:d-1},(_,k)=>`<path class="wb-cut" d="M${48+504*(k+1)/d} ${y}v34"/>`).join('');
  return `<g data-wb-row="${j}"><rect data-wb-whole x="48" y="${y}" width="504" height="34"/>${pieces}${cuts}<rect class="wb-outline" x="48" y="${y}" width="504" height="34"/>${bundled?`<path data-wb-bundle="${j}" d="M46 ${y-4}v44H554v-44Z"/><text x="300" y="${y+63}" text-anchor="middle">Whole bundle ${j+1}</text>`:''}<text x="48" y="${y+83}" text-anchor="middle">${j}</text><text x="552" y="${y+83}" text-anchor="middle">${j+1}</text></g>`;}).join('');
 const row=Math.max(0,rows-1),x=48+504*(n-row*d)/d,y=30+row*step;
 return `<svg ${claim?'data-wb-claim':'data-wb-diagram'} viewBox="0 0 600 ${rows*step+18}" role="img" aria-label="${claim?'Different claim':'Ribbon stock'}: ${count(n,'piece')}, ${d} equal pieces per whole; ${count(m.packed,'whole bundle')} and ${count(m.loose,'loose piece')}.">${strips}<path data-wb-flag="${claim?'different':'current'}" data-endpoint="${x}" d="M${x} ${y+1}V${y-23}l11 5-11 5"/></svg>`;
}
function rowLabels(m){return `<div class="wb-row-labels">${m.rows.map(r=>p(`Length ${r.start} to ${r.end}: ${r.bundled?`whole bundle of ${m.denominator} pieces`:r.filled?count(r.filled,'loose piece'):'empty room'}.`)).join('')}</div>`;}
function material(m){return `<div class="wb-rack" data-wb-model data-packed="${m.packed}" data-loose="${m.loose}" data-numerator="${m.numerator}" data-denominator="${m.denominator}">${p(`One whole contains ${m.denominator} pieces of size 1/${m.denominator}.`)}${diagram(m)}${rowLabels(m)}<div class="wb-counts" role="status">${p(readout(m))}${m.packed===0&&m.numerator>0?p(`${count(m.loose,'piece')} of size 1/${m.denominator}: ${m.loose}/${m.denominator}.`):''}</div></div>`;}
function work(v,m){const c=wholeCases.find(c=>c.id===v.caseId);return `<label class="wb-case">Choose some ribbon stock<select data-wb-case>${wholeCases.map(c=>`<option value="${c.id}"${v.caseId===c.id?' selected':''}>${esc(c.title)}</option>`).join('')}</select></label>${p(copy.story)}${p(copy.instruction)}${p(`Starting name: ${c.sourceWords}.`)}${numeral(c.sourceNumeral)}<div class="wb-workbench">${material(m)}<section class="wb-tools" aria-label="Whole bundle controls"><div class="wb-actions">${button('bundle','Bundle one whole',!m.canBundle)}${button('open','Open one whole',!m.canOpen)}</div>${m.numerator===0?'':p(bundleReason(m))}${!m.canOpen?p('There is no whole bundle to open.'):''}</section></div><div class="wb-actions">${button('names','Two names for the amount')}${button('example','Show me with 7/3')}</div>`;}
function names(v,m){const c=wholeNames(v.cases.get(v.caseId));return `${material(m)}<div class="wb-explanation">${p(c.text,c.spokenText)}${numeral(c.mixedLabel)}</div><div class="wb-actions">${button('back','Back to my ribbons')}${button('example','Show me with 7/3')}</div>`;}
function example(v){const e=wholeExample(v.frame);return `${p('These are separate example ribbons. Your ribbons stay as you left them.')}${material(e)}${v.frame===2?numeral('2 1/3'):''}${e.claim?`<div class="wb-claim">${p('Different claim: 3/3')}${diagram({...e.claim,packed:0,loose:3},true)}</div>`:''}<div class="wb-caption" role="status">${p(`Picture ${v.frame+1} of 6. ${e.text}`,`Picture ${v.frame+1} of 6. ${e.spokenText??e.text}`)}</div><nav class="wb-actions" aria-label="Example pictures">${button('previous','Previous',v.frame===0)}${button('next','Next',v.frame===5)}${button('back',v.caller==='names'?'Back to the names':'Back to my ribbons')}</nav>`;}
export function wholeBundlesPage(book,owner){const v=current(book,owner),m=wholeModel(v.cases.get(v.caseId));return `<section class="wb-page" data-wb-root><h2 id="wb-heading" tabindex="-1" data-wb-read>${v.screen==='work'?'Wholes and pieces':v.screen==='names'?'Two names for the amount':'Show me with 7/3'}</h2><div data-wb-view="${v.screen}"${v.screen==='example'?` data-wb-frame="${v.frame}"`:''}>${v.screen==='example'?example(v):v.screen==='names'?names(v,m):work(v,m)}</div><div class="wb-actions">${hearButton('',v.screen==='example'?'Read this example':v.screen==='names'?'Read these names':'Read these ribbons')}</div>${p(copy.visit)}<details data-wb-grownup${v.grownUp?' open':''}><summary>For grown-ups</summary>${p(copy.grownUp)}</details></section>`;}

// A removed, concealed or reparented control stays retired for this binding.
function bindingGuard(root,valid,stop){const controls=[root,...root.querySelectorAll('button,input,select,a,summary,details')].filter(n=>!n.closest?.('.speech-controls,drawn-howto')),chains=new Map(),retired=new WeakSet();let disconnected=false;
 const chain=n=>{const out=[];for(;n;n=n.parentNode)out.push(n);return out;};for(const n of controls)chains.set(n,chain(n));
 const audit=records=>{for(const r of records){if(r.target.closest?.('.speech-controls,drawn-howto'))continue;if(r.type==='attributes'){for(const n of controls)if(chains.get(n).includes(r.target))retired.add(n);}else for(const removed of r.removedNodes)for(const n of controls)if(chains.get(n).includes(removed)||removed.contains?.(n))retired.add(n);}};
 const disconnect=()=>{disconnected=true;observer.disconnect();};const observer=new MutationObserver(records=>{audit(records);if(!root.isConnected||!valid()||retired.has(root)){stop();disconnect();}});observer.observe(document,{childList:true,subtree:true,attributes:true,attributeFilter:['hidden','inert','aria-hidden','style','class']});
 return {disconnect,accepts(node){audit(observer.takeRecords());if(disconnected||!valid()||!root.isConnected||!root.contains(node)||node.disabled||retired.has(node))return false;const old=chains.get(node),now=chain(node);if(!old||old.length!==now.length||!old.every((n,i)=>n===now[i]))return false;for(let n=node;n?.nodeType===1;n=n.parentElement){const css=getComputedStyle(n);if(n.hidden||n.inert||n.getAttribute('aria-hidden')==='true'||css.display==='none'||['hidden','collapse'].includes(css.visibility))return false;if(n.tagName==='DETAILS'&&!n.open&&n!==node&&!n.querySelector(':scope>summary')?.contains(node))return false;}return node.getClientRects().length>0;}};
}
function visibleNarration(root){return [...root.querySelectorAll('[data-wb-read],label')].filter(n=>{if(n.closest('.speech-controls,drawn-howto'))return false;for(let a=n;a;a=a.parentElement){const css=getComputedStyle(a);if(a.hidden||a.inert||a.getAttribute('aria-hidden')==='true'||css.display==='none'||['hidden','collapse'].includes(css.visibility)||a.tagName==='DETAILS'&&!a.open)return false;}return n.getClientRects().length>0;}).map(n=>n.matches('label')?[...n.childNodes].map(c=>c.nodeType===3?c.textContent:c.tagName==='SELECT'?c.selectedOptions[0]?.textContent:'').join(' '):(n.dataset.wbSpeech??n.textContent)).map(s=>s.replace(/\s+/g,' ').trim()).join(' ');}
export function bindWholeBundles(book,ctx={}){retire();const root=document.querySelector('[data-wb-root]');if(!root||!visit)return;const v=visit,owner=typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId,caseId=v.caseId,material=v.cases.get(caseId),bytes=JSON.stringify(material),screen=v.screen,frame=v.frame,caller=v.caller,parent=root.parentNode;
 const live=()=>root.isConnected&&root.parentNode===parent&&document.querySelector('[data-wb-root]')===root&&location.hash==='#workshop/join-pieces'&&(typeof ctx.notebook==='function'?ctx.notebook():ctx.notebook??book)===book&&(!ctx.isActive||ctx.isActive())&&(typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId)===owner&&visit===v&&v.book===book&&v.owner===owner&&v.caseId===caseId&&v.cases.get(caseId)===material&&JSON.stringify(material)===bytes&&v.screen===screen&&v.frame===frame&&v.caller===caller;
 const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();},guard=bindingGuard(root,live,stop);retire=guard.disconnect;stopBinding=stop;
 for(const c of root.querySelectorAll('button,input,select,a,summary,details')){if(c.closest('.speech-controls,drawn-howto'))continue;for(const type of ['click','input','change','keydown'])c.addEventListener(type,e=>{if(!guard.accepts(c)){e.preventDefault();e.stopImmediatePropagation();}},{capture:true});}
 const redraw=(selector='#wb-heading')=>{guard.disconnect();ctx.render();let target=document.querySelector(selector);if(!target||target.disabled||!target.getClientRects().length)selector='#wb-heading';if(ctx.focus)ctx.focus(selector);else document.querySelector(selector)?.focus();};
 root.querySelector('[data-wb-grownup]')?.addEventListener('toggle',e=>{if(guard.accepts(e.target)&&v.grownUp!==e.target.open){v.grownUp=e.target.open;stop();}});
 root.addEventListener('click',e=>{const b=e.target.closest('[data-speak]');if(!b||!root.contains(b)||b.closest('.speech-controls,drawn-howto'))return;if(!guard.accepts(b)){e.preventDefault();e.stopImmediatePropagation();return;}b.dataset.speak=visibleNarration(root);},{capture:true});
 root.querySelector('[data-wb-case]')?.addEventListener('change',e=>{if(!guard.accepts(e.target)||screen!=='work'||!v.cases.has(e.target.value)||caseId===e.target.value)return;stop();v.caseId=e.target.value;redraw('[data-wb-case]');});
 root.querySelectorAll('[data-wb-action]').forEach(b=>b.addEventListener('click',()=>{if(!guard.accepts(b))return;const a=b.dataset.wbAction;
  if(a==='example'&&screen!=='example'){stop();v.caller=screen;v.screen='example';v.frame=0;redraw();return;}
  if(a==='back'&&screen!=='work'){stop();v.screen=screen==='example'?caller:'work';redraw(`[data-wb-action="${screen==='example'?'example':'names'}"]`);return;}
  if(screen==='example'&&['previous','next'].includes(a)){const n=frame+(a==='next'?1:-1);if(!wholeExample(n))return;stop();v.frame=n;redraw(`[data-wb-action="${n===5?'previous':n===0?'next':a}"]`);return;}
  if(screen!=='work')return;if(a==='names'){stop();v.screen='names';redraw();return;}
  if(a!=='bundle'&&a!=='open')return;const next=changeWhole(material,a);if(!next)return;stop();v.cases.set(caseId,next);const m=wholeModel(next),focus=a==='bundle'?(m.canBundle?'bundle':m.canOpen?'open':null):(m.canOpen?'open':m.canBundle?'bundle':null);redraw(focus?`[data-wb-action="${focus}"]`:'#wb-heading');
 }));
}
